from qiskit import QuantumCircuit
from qiskit.transpiler import generate_preset_pass_manager

# The five pass-manager runs MUST mirror data/figures/s3-q057/generate.py —
# the rendered figures are mpl drawings of exactly these outputs.


def build(z_pair=True, cx_pair=True, once=False):
    qc = QuantumCircuit(3)
    qc.h(0)
    if cx_pair or once:
        qc.cx(0, 1)
    if cx_pair and not once:
        qc.cx(0, 1)
    qc.t(1)
    qc.h(2)
    if z_pair or once:
        qc.z(2)
    if z_pair and not once:
        qc.z(2)
    qc.cx(1, 2)
    qc.cx(0, 2)
    return qc


def run(circ, level):
    pm = generate_preset_pass_manager(optimization_level=level,
                                      seed_transpiler=42)
    return pm.run(circ)


VARIANTS = {
    "A": run(build(), 2),
    "B": run(build(z_pair=False), 0),
    "C": run(build(), 0),
    "D": run(build(cx_pair=False), 0),
    "E": run(build(once=True), 0),
}


def sig(circ):
    """What the drawer receives: the wire count and the gate sequence
    addressed by qubit index (no layout is set, so the wires are q_0..q_2)."""
    return circ.num_qubits, tuple(
        (inst.operation.name, tuple(circ.find_bit(b).index for b in inst.qubits))
        for inst in circ.data
    )


target = sig(run(build(), 0))
proven, evidence, observed = [], {}, {}
for key, circ in sorted(VARIANTS.items()):
    s = sig(circ)
    match = s == target
    observed[key] = {"num_qubits": s[0],
                     "ops": [[n, list(q)] for n, q in s[1]]}
    evidence[key] = (
        f"pass-manager output draws {s[0]} wires carrying "
        + ", ".join(f"{n}{list(q)}" for n, q in s[1])
        + f" ({len(s[1])} gates) -> match={match}"
    )
    if match:
        proven.append(key)

observed["stem"] = {"num_qubits": target[0],
                    "ops": [[n, list(q)] for n, q in target[1]]}
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
